* { box-sizing: border-box; }

:root {
  --navy: #10304a;
  --navy-soft: #1d4a6b;
  --teal: #17a2a2;
  --aqua: #6fd3d3;
  --sand: #f4efe6;
  --ink: #1c2733;
  --muted: #5d6b7a;
  --line: #d7dfe7;
  --white: #ffffff;
}

html, body { margin: 0; padding: 0; }

body {
  min-height: 100vh;
  background: radial-gradient(circle at 12% 0%, #e8f2f5 0%, #f6f4ef 46%, #eef1f4 100%);
  color: var(--ink);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", "Noto Sans CJK SC", sans-serif;
  line-height: 1.55;
}

.app {
  max-width: 1180px;
  margin: 0 auto;
  padding: 18px 20px 26px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-height: 100vh;
}

/* ---------- Top bar ---------- */
.topbar {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 10px 16px;
  background: rgba(255,255,255,0.86);
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: 0 6px 20px rgba(16,48,74,0.06);
}

.brand { display: flex; align-items: center; gap: 12px; min-width: 0; }

.brand-mark {
  width: 42px; height: 42px; flex: 0 0 auto;
  border-radius: 11px;
  background: linear-gradient(135deg, var(--navy) 0%, var(--teal) 100%);
  color: #fff;
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 0.5px;
  display: grid; place-items: center;
}

.brand-text h1 { margin: 0; font-size: 16px; letter-spacing: 0.5px; color: var(--navy); }
.brand-text p { margin: 0; font-size: 12px; color: var(--muted); }

.progress-wrap { flex: 1 1 auto; min-width: 60px; }

.progress-track {
  height: 8px;
  border-radius: 999px;
  background: #e3e9ee;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 12.5%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--navy) 0%, var(--teal) 100%);
  transition: width 220ms ease;
}

.counter {
  flex: 0 0 auto;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  font-size: 14px;
  color: var(--navy);
  background: #eef6f7;
  border: 1px solid #cfe6e7;
  padding: 4px 12px;
  border-radius: 999px;
}

/* ---------- Deck stage ---------- */
.deck-stage {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px 0;
}

.deck-canvas {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 16px;
  box-shadow: 0 14px 36px rgba(16,48,74,0.14);
  overflow: hidden;
}

.slide {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
}

.slide[hidden] { display: none; }

.slide-cover {
  background: linear-gradient(135deg, #0e2c44 0%, #134b66 55%, #17827f 100%);
  color: #fff;
}

.slide-inner {
  flex: 1 1 auto;
  padding: clamp(18px, 3.4vw, 44px) clamp(18px, 4vw, 56px);
  display: flex;
  flex-direction: column;
  gap: clamp(8px, 1.4vw, 16px);
  min-height: 0;
  overflow: hidden;
}

/* ---------- Common slide text ---------- */
.eyebrow {
  margin: 0;
  font-size: clamp(10px, 1vw, 13px);
  letter-spacing: 0.14em;
  font-weight: 700;
  color: var(--teal);
  text-transform: uppercase;
}

.slide-cover .eyebrow { color: var(--aqua); }

.slide-head h2 {
  margin: 2px 0 0;
  font-size: clamp(17px, 2.5vw, 32px);
  line-height: 1.25;
  color: var(--navy);
  letter-spacing: 0.01em;
}

.slide-foot {
  margin: auto 0 0;
  padding-top: 8px;
  font-size: clamp(10px, 1.05vw, 13px);
  color: var(--muted);
  border-top: 1px dashed var(--line);
}

/* ---------- Cover ---------- */
.cover-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: clamp(14px, 3vw, 40px);
  align-items: center;
}

.cover-main { display: flex; flex-direction: column; gap: clamp(6px, 1.2vw, 14px); }

.cover-title {
  margin: 0;
  font-size: clamp(30px, 5.4vw, 66px);
  line-height: 1.08;
  letter-spacing: 0.02em;
  font-weight: 800;
}

.cover-sub {
  margin: 0;
  font-size: clamp(11px, 1.35vw, 16px);
  color: rgba(255,255,255,0.86);
  max-width: 34ch;
}

.cover-meta { display: flex; flex-wrap: wrap; gap: 8px; }

.pill {
  font-size: clamp(10px, 1vw, 12px);
  padding: 4px 12px;
  border-radius: 999px;
  background: rgba(255,255,255,0.14);
  border: 1px solid rgba(255,255,255,0.3);
  color: #eafbfb;
}

.cover-side {
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.25);
  border-radius: 14px;
  padding: clamp(12px, 2vw, 22px);
  backdrop-filter: blur(2px);
}

.cover-side h3 {
  margin: 0 0 10px;
  font-size: clamp(13px, 1.5vw, 18px);
  color: #fff;
}

.mini-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }

.mini-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: clamp(10px, 1.15vw, 14px);
  color: #eaf6f6;
}

.day-badge {
  flex: 0 0 auto;
  width: 30px; height: 22px;
  display: grid; place-items: center;
  border-radius: 6px;
  background: var(--aqua);
  color: #0d2c3f;
  font-weight: 800;
  font-size: 11px;
}

.note {
  margin: 12px 0 0;
  font-size: clamp(9px, 1vw, 12px);
  color: rgba(255,255,255,0.72);
  border-top: 1px solid rgba(255,255,255,0.22);
  padding-top: 10px;
}

/* ---------- Flow (overview) ---------- */
.flow {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: 1fr auto 1fr auto 1fr;
  align-items: stretch;
  gap: clamp(6px, 1vw, 14px);
  min-height: 0;
}

.flow-step {
  background: #f7fafb;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: clamp(10px, 1.6vw, 20px);
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 0;
}

.flow-num {
  align-self: flex-start;
  font-weight: 800;
  font-size: clamp(11px, 1.1vw, 13px);
  color: #fff;
  background: var(--navy);
  border-radius: 6px;
  padding: 2px 9px;
}

.flow-step h3 {
  margin: 2px 0 0;
  font-size: clamp(12px, 1.45vw, 18px);
  color: var(--navy-soft);
}

.flow-step p {
  margin: 0;
  font-size: clamp(10px, 1.1vw, 13px);
  color: var(--muted);
}

.flow-tag {
  margin-top: auto !important;
  font-size: clamp(9px, 1vw, 12px) !important;
  color: var(--teal) !important;
  font-weight: 700;
}

.flow-arrow {
  display: grid;
  place-items: center;
  font-size: clamp(16px, 2.2vw, 28px);
  color: var(--aqua);
  font-weight: 700;
}

/* ---------- Compare table ---------- */
.compare-table {
  width: 100%;
  border-collapse: collapse;
  font-size: clamp(10px, 1.12vw, 14px);
  table-layout: fixed;
}

.compare-table caption {
  caption-side: top;
  text-align: left;
  font-size: clamp(9px, 1vw, 12px);
  color: var(--muted);
  padding-bottom: 6px;
}

.compare-table th,
.compare-table td {
  border-bottom: 1px solid var(--line);
  padding: clamp(6px, 1vw, 12px) clamp(6px, 0.9vw, 12px);
  text-align: left;
  vertical-align: top;
  word-break: break-word;
}

.compare-table thead th {
  background: #eef6f7;
  color: var(--navy);
  font-weight: 700;
  border-bottom: 2px solid var(--aqua);
}

.compare-table tbody th {
  color: var(--navy-soft);
  font-weight: 700;
  background: #fbfcfd;
}

/* ---------- Timeline ---------- */
.timeline {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: clamp(4px, 0.7vw, 8px);
  min-height: 0;
}

.time-row {
  display: grid;
  grid-template-columns: clamp(48px, 7vw, 84px) 1fr;
  gap: clamp(8px, 1.4vw, 16px);
  align-items: stretch;
  background: #f8fafb;
  border: 1px solid var(--line);
  border-left: 4px solid var(--teal);
  border-radius: 10px;
  padding: clamp(6px, 1vw, 12px) clamp(8px, 1.2vw, 16px);
}

.time {
  font-weight: 800;
  color: var(--navy);
  font-size: clamp(10px, 1.1vw, 14px);
  display: flex;
  align-items: center;
}

.time-body h3 {
  margin: 0;
  font-size: clamp(11px, 1.3vw, 16px);
  color: var(--navy-soft);
}

.time-body p {
  margin: 2px 0 0;
  font-size: clamp(9px, 1.05vw, 13px);
  color: var(--muted);
}

/* ---------- Two column ---------- */
.two-col {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(10px, 1.6vw, 20px);
  min-height: 0;
}

.col-card {
  background: #f8fafb;
  border: 1px solid var(--line);
  border-top: 4px solid var(--teal);
  border-radius: 12px;
  padding: clamp(10px, 1.6vw, 20px);
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 0;
  overflow: hidden;
}

.col-card h3 {
  margin: 0;
  font-size: clamp(12px, 1.4vw, 17px);
  color: var(--navy);
}

.col-card p {
  margin: 0;
  font-size: clamp(10px, 1.08vw, 13px);
  color: var(--muted);
}

.check-list {
  margin: 4px 0 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.check-list li {
  position: relative;
  padding-left: 18px;
  font-size: clamp(9px, 1.04vw, 13px);
  color: var(--ink);
}

.check-list li::before {
  content: "✓";
  position: absolute;
  left: 0;
  top: 0;
  color: var(--teal);
  font-weight: 800;
  font-size: 11px;
}

.callout {
  margin-top: auto;
  background: #eef6f7;
  border: 1px dashed #a9d6d8;
  border-radius: 10px;
  padding: clamp(6px, 1vw, 12px) clamp(8px, 1.2vw, 16px);
  font-size: clamp(9px, 1.05vw, 13px);
  color: #14565a;
}

/* ---------- Chart ---------- */
.chart-wrap {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: 2.4fr 1fr;
  gap: clamp(10px, 2vw, 28px);
  align-items: center;
  min-height: 0;
}

.chart {
  display: flex;
  flex-direction: column;
  gap: clamp(8px, 1.4vw, 16px);
  min-width: 0;
}

.bar-row {
  display: grid;
  grid-template-columns: clamp(50px, 6.5vw, 78px) 1fr clamp(56px, 7vw, 84px);
  align-items: center;
  gap: clamp(6px, 1vw, 12px);
  font-size: clamp(10px, 1.06vw, 13px);
}

.bar-label { color: var(--navy-soft); font-weight: 700; }

.bar-track {
  height: clamp(14px, 2vw, 26px);
  background: #eef1f4;
  border-radius: 6px;
  overflow: hidden;
}

.bar { height: 100%; border-radius: 6px; }

.bar-a { background: var(--navy); }
.bar-b { background: var(--teal); }
.bar-c { background: #4b8fa8; }
.bar-d { background: #9dc5cc; }

.bar-value { text-align: right; color: var(--muted); font-variant-numeric: tabular-nums; }

.legend-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: clamp(8px, 1.4vw, 18px);
  font-size: clamp(9px, 1.02vw, 12px);
  color: var(--muted);
}

.legend-row.vertical {
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  background: #f8fafb;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: clamp(8px, 1.4vw, 16px);
}

.legend-item { display: inline-flex; align-items: center; gap: 6px; }

.dot {
  width: 10px; height: 10px;
  border-radius: 3px;
  display: inline-block;
}

.dot-a { background: var(--navy); }
.dot-b { background: var(--teal); }
.dot-c { background: #4b8fa8; }
.dot-d { background: #9dc5cc; }

.legend-note {
  margin-left: auto;
  color: #8593a1;
}

.legend-row.vertical .legend-note { margin: 6px 0 0; }

/* ---------- Note save box ---------- */
.filler-box {
  margin-top: auto;
  background: #f8fafb;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: clamp(8px, 1.4vw, 16px);
}

.filler-box label {
  display: block;
  font-size: clamp(9px, 1.04vw, 13px);
  font-weight: 700;
  color: var(--navy-soft);
  margin-bottom: 6px;
}

.note-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.note-row input {
  flex: 1 1 200px;
  min-width: 0;
  font: inherit;
  font-size: clamp(10px, 1.06vw, 13px);
  padding: 8px 12px;
  border: 1px solid #c9d5de;
  border-radius: 8px;
  background: #fff;
  color: var(--ink);
}

.note-row input:focus {
  outline: 2px solid var(--teal);
  outline-offset: 1px;
  border-color: var(--teal);
}

.note-status {
  margin: 8px 0 0;
  font-size: clamp(9px, 1vw, 12px);
  color: var(--muted);
}

.note-status.ok { color: #16766b; }
.note-status.err { color: #b23b3b; }

/* ---------- Conclusion ---------- */
.conclusion-grid {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: clamp(10px, 1.8vw, 22px);
  min-height: 0;
}

.conclusion-main,
.conclusion-side {
  border-radius: 12px;
  padding: clamp(10px, 1.6vw, 20px);
  min-height: 0;
}

.conclusion-main {
  background: linear-gradient(160deg, #eef6f7 0%, #f8fafb 100%);
  border: 1px solid #bfe0e2;
}

.conclusion-side {
  background: #fbfaf6;
  border: 1px solid #e8e0cc;
}

.conclusion-main h3,
.conclusion-side h3 {
  margin: 0 0 8px;
  font-size: clamp(12px, 1.4vw, 17px);
  color: var(--navy);
}

.num-list {
  margin: 0;
  padding-left: 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: clamp(10px, 1.1vw, 14px);
  color: var(--ink);
}

.num-list li::marker { color: var(--teal); font-weight: 800; }

/* ---------- Nav bar ---------- */
.nav-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: rgba(255,255,255,0.86);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 10px 14px;
}

.nav-hint {
  font-size: 12px;
  color: var(--muted);
  text-align: center;
  flex: 1 1 auto;
}

.btn {
  font: inherit;
  font-size: 14px;
  font-weight: 700;
  border-radius: 10px;
  border: 1px solid #c9d5de;
  background: #fff;
  color: var(--navy);
  padding: 9px 18px;
  cursor: pointer;
  transition: transform 120ms ease, background 160ms ease, box-shadow 160ms ease;
  min-width: 96px;
}

.btn:hover:not(:disabled) { background: #f1f7f8; }
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:focus-visible { outline: 2px solid var(--teal); outline-offset: 2px; }

.btn.primary {
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-soft) 100%);
  border-color: var(--navy);
  color: #fff;
}

.btn.primary:hover:not(:disabled) { background: linear-gradient(135deg, #143a58 0%, #23577b 100%); }

.btn:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.btn.small {
  min-width: 0;
  padding: 8px 16px;
  font-size: 13px;
}

/* ---------- Responsive ---------- */
@media (max-width: 760px) {
  .app { padding: 12px 10px 18px; gap: 10px; }
  .topbar { padding: 8px 10px; gap: 10px; flex-wrap: wrap; }
  .brand-mark { width: 34px; height: 34px; border-radius: 9px; font-size: 12px; }
  .brand-text h1 { font-size: 14px; }
  .brand-text p { font-size: 10px; }
  .progress-wrap { order: 3; flex-basis: 100%; }
  .counter { margin-left: auto; font-size: 12px; padding: 3px 10px; }

  .cover-grid { grid-template-columns: 1fr; align-items: start; gap: 10px; }
  .cover-side { padding: 10px; }
  .cover-title { font-size: clamp(24px, 8vw, 40px); }
  .cover-sub { font-size: 11px; }

  .flow { grid-template-columns: 1fr; }
  .flow-arrow { display: none; }
  .flow-step { padding: 8px 10px; }
  .flow-step p { font-size: 10px; }

  .chart-wrap { grid-template-columns: 1fr; }
  .legend-row.vertical { flex-direction: row; flex-wrap: wrap; }

  .two-col, .conclusion-grid { grid-template-columns: 1fr; }
  .slide-inner { padding: 14px 14px; gap: 8px; }
  .nav-hint { display: none; }
  .nav-bar { padding: 8px 10px; }
  .btn { min-width: 84px; padding: 8px 12px; font-size: 13px; }
}

@media (max-height: 620px) {
  .nav-hint { display: none; }
}

