(function () {
  'use strict';

  var PAGE_KEY = 'shenzhen_deck_page';

  function safeGet(key, fallback) {
    try {
      if (window.atoms && typeof window.atoms.storage.get === 'function') {
        var v = window.atoms.storage.get(key, fallback);
        return v === undefined ? fallback : v;
      }
    } catch (e) { /* ignore */ }
    return fallback;
  }

  function safeSet(key, value) {
    try {
      if (window.atoms && typeof window.atoms.storage.set === 'function') {
        window.atoms.storage.set(key, value);
      }
    } catch (e) { /* ignore */ }
  }

  var slides = Array.prototype.slice.call(document.querySelectorAll('[data-deck-slide]'));
  var total = slides.length;

  var prevBtn = document.querySelector('[data-deck-prev]');
  var nextBtn = document.querySelector('[data-deck-next]');
  var positionEl = document.querySelector('[data-deck-position]');
  var progressFill = document.getElementById('progressFill');
  var noteInput = document.getElementById('tripNote');
  var saveNoteBtn = document.getElementById('saveNote');
  var noteStatus = document.getElementById('noteStatus');

  var current = 0;

  function normalizeIndex(n) {
    var i = parseInt(n, 10);
    if (isNaN(i)) { return 0; }
    if (i < 0) { return 0; }
    if (i > total - 1) { return total - 1; }
    return i;
  }

  function render() {
    for (var i = 0; i < total; i++) {
      var el = slides[i];
      if (i === current) {
        el.removeAttribute('hidden');
      } else {
        el.setAttribute('hidden', '');
      }
    }

    if (positionEl) {
      positionEl.textContent = (current + 1) + ' / ' + total;
    }

    if (progressFill) {
      progressFill.style.width = (((current + 1) / total) * 100) + '%';
    }

    if (prevBtn) { prevBtn.disabled = current <= 0; }
    if (nextBtn) { nextBtn.disabled = current >= total - 1; }
  }

  function goTo(index, persist) {
    var next = normalizeIndex(index);
    var changed = next !== current;
    current = next;
    render();
    if (persist !== false && changed) {
      safeSet(PAGE_KEY, current + 1);
    }
  }

  function setupNavigation() {
    if (prevBtn) {
      prevBtn.addEventListener('click', function () {
        if (current <= 0) { return; }
        goTo(current - 1, true);
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function () {
        if (current >= total - 1) { return; }
        goTo(current + 1, true);
      });
    }

    document.addEventListener('keydown', function (event) {
      if (event.defaultPrevented) { return; }
      if (event.altKey || event.ctrlKey || event.metaKey) { return; }

      var target = event.target;
      if (target && target.nodeType === 1) {
        var tag = target.tagName;
        if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || target.isContentEditable) {
          return;
        }
      }

      var key = event.key;

      if (key === 'ArrowRight' || key === 'Right') {
        event.preventDefault();
        if (current < total - 1) { goTo(current + 1, true); }
      } else if (key === 'ArrowLeft' || key === 'Left') {
        event.preventDefault();
        if (current > 0) { goTo(current - 1, true); }
      } else if (key === 'Home') {
        event.preventDefault();
        goTo(0, true);
      } else if (key === 'End') {
        event.preventDefault();
        goTo(total - 1, true);
      }
    });
  }

  function setStatus(text, kind) {
    if (!noteStatus) { return; }
    noteStatus.textContent = text;
    noteStatus.className = 'note-status' + (kind ? ' ' + kind : '');
  }

  function saveNote() {
    if (!noteInput) { return; }
    var value = noteInput.value.trim();
    if (value.length === 0) {
      setStatus('请输入备注内容后再保存。', 'err');
      noteInput.focus();
      return;
    }
    try {
      if (window.atoms && typeof window.atoms.storage.set === 'function') {
        window.atoms.storage.set('shenzhen_trip_note', value);
        setStatus('已保存到本机：' + value, 'ok');
      } else {
        setStatus('存储不可用，本次未保存。', 'err');
      }
    } catch (e) {
      setStatus('保存失败，请稍后重试。', 'err');
    }
  }

  function setupNote() {
    if (!noteInput || !saveNoteBtn) { return; }

    var saved = safeGet('shenzhen_trip_note', '');
    if (typeof saved === 'string' && saved.length > 0) {
      noteInput.value = saved;
      setStatus('已载入上次保存的备注。', 'ok');
    } else {
      setStatus('尚未保存备注', '');
    }

    saveNoteBtn.addEventListener('click', saveNote);

    noteInput.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' && !event.isComposing) {
        event.preventDefault();
        saveNote();
      }
    });
  }

  function init() {
    if (!slides.length) { return; }

    var stored = safeGet(PAGE_KEY, 1);
    var storedNum = parseInt(stored, 10);
    if (isNaN(storedNum)) { storedNum = 1; }
    current = normalizeIndex(storedNum - 1);

    setupNavigation();
    setupNote();
    render();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true });
  } else {
    init();
  }
})();
